__d(function(g,r,i,a,m,e,_d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEGAL_DRAFT",{enumerable:!0,get:function(){return l}}),Object.defineProperty(e,"LEGAL_DOCS",{enumerable:!0,get:function(){return s}}),Object.defineProperty(e,"legalDoc",{enumerable:!0,get:function(){return t}});const l=!0,n='[\u015e\u0130RKET \xdcNVANI], [ADRES], MERS\u0130S No: [MERS\u0130S], KEP: [KEP ADRES\u0130]',k='destek@vopila.com',s=[{key:'aydinlatma',title:'Ayd\u0131nlatma Metni ve Gizlilik Politikas\u0131',updated:'28 Ekim 2026',intro:'6698 say\u0131l\u0131 Ki\u015fisel Verilerin Korunmas\u0131 Kanunu (KVKK) md. 10 uyar\u0131nca, VOPILA uygulamas\u0131n\u0131 kullan\u0131rken ki\u015fisel verilerinin nas\u0131l i\u015flendi\u011fini a\xe7\u0131klar\u0131z.',sections:[{h:'1. Veri sorumlusu',p:[`Veri sorumlusu: ${n}. \u0130leti\u015fim: ${k}.`]},{h:'2. \u0130\u015fledi\u011fimiz veriler',p:['Kimlik ve hesap: ad soyad, kullan\u0131c\u0131 ad\u0131, profil foto\u011fraf\u0131, biyografi, yazd\u0131\u011f\u0131n konum bilgisi.','\u0130leti\u015fim: e-posta adresi; sipari\u015f verirsen telefon numaras\u0131 ve teslimat adresi.','Ya\u015f grubu: do\u011fum tarihin SAKLANMAZ. Yaln\u0131zca ya\u015f grubun (15\u201318 / 18+) ve ya\u015f grubunun de\u011fi\u015fece\u011fi ay tutulur. e-Devlet do\u011frulamas\u0131nda yaln\u0131zca 15 ve 18 ya\u015f\u0131ndan b\xfcy\xfck olup olmad\u0131\u011f\u0131n bildirilir; ad\u0131n, T.C. kimlik numaran ve do\u011fum tarihin bize iletilmez.','\u0130\xe7erik: payla\u015ft\u0131\u011f\u0131n foto\u011fraf, video, yorum, an, mesaj, arena kat\u0131l\u0131m\u0131 ve oylar\u0131n.','Etkile\u015fim: be\u011feni, kaydetme, takip, ilgi alanlar\u0131n (hangi konulara ne kadar bakt\u0131\u011f\u0131n \u2014 \xf6neriler i\xe7in).','\u0130\u015flem g\xfcvenli\u011fi: oturum kay\u0131tlar\u0131, iki ad\u0131ml\u0131 do\u011frulama bilgisi, hile ve k\xf6t\xfcye kullan\u0131m tespiti kay\u0131tlar\u0131.','C\xfczdan ve sipari\u015fler: token hareketleri, sipari\u015f ve kargo bilgileri.','Kullan\u0131m s\xfcresi bilgisi yaln\u0131zca kendi telefonunda tutulur, sunucuya g\xf6nderilmez.']},{h:'3. Ama\xe7lar ve hukuki sebepler',p:['Hesab\u0131n\u0131 a\xe7mak, hizmeti sunmak, arena yar\u0131\u015fmalar\u0131n\u0131 y\xfcr\xfctmek, \xf6d\xfclleri ve sipari\u015fleri teslim etmek \u2014 s\xf6zle\u015fmenin kurulmas\u0131 ve ifas\u0131 (KVKK md. 5/2-c).','Ya\u015f do\u011frulama, 15 ya\u015f alt\u0131na hizmet vermeme ve 15\u201318 ya\u015f korumalar\u0131, yetkili mercilerin taleplerinin kar\u015f\u0131lanmas\u0131, fatura ve kay\u0131t saklama \u2014 hukuki y\xfck\xfcml\xfcl\xfck (KVKK md. 5/2-\xe7; 5651 say\u0131l\u0131 Kanun, Sosyal A\u011f Sa\u011flay\u0131c\u0131larda Ya\u015f Do\u011frulama Y\xf6netmeli\u011fi, vergi mevzuat\u0131).','G\xfcvenlik, hile tespiti, \xf6neri ve s\u0131ralama algoritmalar\u0131 \u2014 me\u015fru menfaat (KVKK md. 5/2-f). 18 ya\u015f alt\u0131 kullan\u0131c\u0131lara profil \xe7\u0131kar\u0131m\u0131na dayal\u0131 reklam g\xf6sterilmez.','Hukuken a\xe7\u0131k r\u0131za gereken bir i\u015flem olursa ayr\u0131ca onay\u0131n istenir.']},{h:'4. Aktar\u0131m',p:['Verilerin sat\u0131lmaz. Yaln\u0131zca hizmet i\xe7in gerekli oldu\u011fu kadar \u015fu taraflarla payla\u015f\u0131l\u0131r: altyap\u0131 sa\u011flay\u0131c\u0131m\u0131z (veritaban\u0131 ve dosya bar\u0131nd\u0131rma: Supabase \u2014 sunucu konumu: [\xdcLKE]), e-posta g\xf6nderim hizmeti (Resend), anla\u015fmal\u0131 kargo firmas\u0131 (yaln\u0131zca sipari\u015f teslimi i\xe7in ad, telefon, adres), kanunen yetkili kamu kurumlar\u0131.','Yurt d\u0131\u015f\u0131ndaki hizmet sa\u011flay\u0131c\u0131lara aktar\u0131m KVKK md. 9 kapsam\u0131nda [standart s\xf6zle\u015fme / ilgili g\xfcvence] ile yap\u0131l\u0131r.']},{h:'5. Saklama s\xfcreleri',p:['Hesap verileri hesab\u0131n a\xe7\u0131k oldu\u011fu s\xfcrece saklan\u0131r. Hesab\u0131n\u0131 sildi\u011finde profilin, i\xe7eriklerin ve mesajlar\u0131n silinir.','Sipari\u015f ve fatura kay\u0131tlar\u0131 vergi mevzuat\u0131 gere\u011fi yasal s\xfcre boyunca kimliksizle\u015ftirilerek saklan\u0131r.','Otomatik haberler 7 g\xfcn sonra silinir. Ya\u015f itiraz\u0131 s\xfcren hesaplar\u0131n verileri itiraz sonu\xe7lanana kadar silinmez.','5651 say\u0131l\u0131 Kanun kapsam\u0131ndaki trafik bilgileri mevzuatta belirtilen s\xfcre boyunca saklan\u0131r.']},{h:'6. Haklar\u0131n (KVKK md. 11)',p:['Verilerinin i\u015flenip i\u015flenmedi\u011fini \xf6\u011frenme, bilgi isteme, amac\u0131na uygun kullan\u0131l\u0131p kullan\u0131lmad\u0131\u011f\u0131n\u0131 \xf6\u011frenme, aktar\u0131ld\u0131\u011f\u0131 ki\u015fileri bilme, d\xfczeltilmesini, silinmesini ya da yok edilmesini isteme, itiraz etme ve zarar\u0131n giderilmesini talep etme haklar\u0131n vard\u0131r.','Verilerinin kopyas\u0131n\u0131 Ayarlar > Verilerimi indir, hesab\u0131n\u0131 Ayarlar > Hesab\u0131 sil ile kendin alabilir / silebilirsin.',`Di\u011fer talepler i\xe7in ${k} adresine ya da ${n} adresine yaz\u0131l\u0131 ba\u015fvurabilirsin. Ba\u015fvurular en ge\xe7 30 g\xfcn i\xe7inde \xfccretsiz yan\u0131tlan\u0131r.`]}]},{key:'kosullar',title:'Kullan\u0131m Ko\u015fullar\u0131',updated:'28 Ekim 2026',intro:`Bu ko\u015fullar VOPILA uygulamas\u0131n\u0131 kullanman i\xe7in ${n} ile arandaki s\xf6zle\u015fmedir.`,sections:[{h:'1. Kimler kullanabilir',p:['15 ya\u015f\u0131n\u0131 doldurmam\u0131\u015f ki\u015filer VOPILA\u2019y\u0131 kullanamaz (5651 say\u0131l\u0131 Kanun ek md. 4). 15\u201318 ya\u015f aras\u0131ndaki kullan\u0131c\u0131lar i\xe7in ek korumalar uygulan\u0131r; ayr\u0131nt\u0131lar \u201c\xc7ocuklar\u0131 Koruma \xd6nlemleri\u201d sayfas\u0131ndad\u0131r.','Do\u011fum tarihini do\u011fru beyan etmelisin. Yanl\u0131\u015f beyan tespit edilirse hesab\u0131n ask\u0131ya al\u0131nabilir veya kapat\u0131labilir; itiraz hakk\u0131n sakl\u0131d\u0131r.']},{h:'2. Hesab\u0131n',p:['Hesab\u0131n\u0131n g\xfcvenli\u011finden sen sorumlusun. \u0130ki ad\u0131ml\u0131 do\u011frulamay\u0131 a\xe7man\u0131 \xf6neririz.','Ba\u015fkas\u0131 ad\u0131na hesap a\xe7amaz, hesab\u0131n\u0131 devredemez ya da satamazs\u0131n. Bir telefon numaras\u0131 yaln\u0131zca bir hesapta arena ve sipari\u015f do\u011frulamas\u0131 i\xe7in kullan\u0131labilir.']},{h:'3. \u0130\xe7eriklerin',p:['Payla\u015ft\u0131\u011f\u0131n i\xe7eriklerin haklar\u0131 sende kal\u0131r. VOPILA\u2019ya, i\xe7eri\u011fi uygulamada g\xf6stermek, arenalarda yar\u0131\u015ft\u0131rmak ve tan\u0131tmak i\xe7in d\xfcnya \xe7ap\u0131nda, \xfccretsiz, devredilemez bir kullan\u0131m izni verirsin; i\xe7eri\u011fi sildi\u011finde izin sona erer.','Telif hakk\u0131 sana ait olmayan, ba\u015fkas\u0131n\u0131n ki\u015filik haklar\u0131n\u0131 ihlal eden, nefret s\xf6ylemi, taciz, \u015fiddet, m\xfcstehcenlik veya yasa d\u0131\u015f\u0131 i\xe7erik payla\u015famazs\u0131n. Bu i\xe7erikler kald\u0131r\u0131l\u0131r; tekrar\u0131nda hesap ask\u0131ya al\u0131n\u0131r ya da kapat\u0131l\u0131r.','Yapay zek\xe2 ile \xfcretilmi\u015f i\xe7erikleri bu \u015fekilde belirtmelisin.']},{h:'4. Arenalar, token ve \xf6d\xfcller',p:['Arena sezonlar\u0131 her ay\u0131n 1\u2019inde ba\u015flar, ay\u0131n son g\xfcn\xfc saat 24:00\u2019te (T\xfcrkiye saati) biter; ilk \xfc\xe7 s\u0131ra ilan edilir ve \xf6d\xfcller verilir.','Token yaln\u0131zca arena yar\u0131\u015fmalar\u0131nda kazan\u0131l\u0131r; para ile sat\u0131n al\u0131namaz, nakde \xe7evrilemez, devredilemez. Tokenlar yaln\u0131zca VOPILA Ma\u011fazas\u0131\u2019ndaki \xfcr\xfcnler i\xe7in kullan\u0131labilir.','Sahte hesap, oy al\u0131\u015fveri\u015fi, otomatik ara\xe7 kullan\u0131m\u0131 gibi hileler tespit edilirse oylar, tokenlar ve \xf6d\xfcller iptal edilir. \u015e\xfcpheli \xf6d\xfcller y\xf6netici incelemesine al\u0131n\u0131r.','[\xd6d\xfcl ve promosyon mevzuat\u0131 (vergi, \xe7ekili\u015f izni) hukuk\xe7u ve muhasebeci g\xf6r\xfc\u015f\xfcne g\xf6re tamamlanacak.]']},{h:'5. Ma\u011faza ve teslimat',p:['\xdcr\xfcnler stokla s\u0131n\u0131rl\u0131d\u0131r. Sipari\u015fin \u201cHaz\u0131rlan\u0131yor\u201d a\u015famas\u0131ndayken iptal edilirse tokenlar\u0131n iade edilir.','Teslimat anla\u015fmal\u0131 kargo firmas\u0131yla yap\u0131l\u0131r. Hatal\u0131 ya da eksik adres nedeniyle teslim edilemeyen sipari\u015flerden VOPILA sorumlu de\u011fildir.']},{h:'6. Haberler',p:['Haberler sekmesindeki otomatik haberler, kaynaklar\u0131n herkese a\xe7\u0131k haber ak\u0131\u015flar\u0131ndan al\u0131nan ba\u015fl\u0131k ve k\u0131sa \xf6zetlerden olu\u015fur; haberin tamam\u0131 kayna\u011f\u0131n sitesinde okunur ve t\xfcm haklar\u0131 kayna\u011fa aittir.']},{h:'7. Hizmetin de\u011fi\u015fmesi ve sona ermesi',p:['Ko\u015fullar\u0131 de\u011fi\u015ftirebiliriz; \xf6nemli de\u011fi\u015fiklikleri uygulama i\xe7inden \xf6nceden duyururuz.','Bu ko\u015fullar\u0131 ihlal eden hesaplar\u0131 ask\u0131ya alabilir veya kapatabiliriz. Hesab\u0131n\u0131 diledi\u011fin zaman Ayarlar > Hesab\u0131 sil ile kapatabilirsin.']},{h:'8. Uygulanacak hukuk',p:['Bu ko\u015fullara T\xfcrkiye Cumhuriyeti hukuku uygulan\u0131r. Uyu\u015fmazl\u0131klarda [\u0130L] mahkemeleri ve icra daireleri yetkilidir; t\xfcketici haklar\u0131n sakl\u0131d\u0131r.']}]},{key:'cocuk-koruma',title:'\xc7ocuklar\u0131 Koruma \xd6nlemleri',updated:'28 Ekim 2026',intro:'Sosyal A\u011f Sa\u011flay\u0131c\u0131larda Ya\u015f Do\u011frulama Y\xf6netmeli\u011fi (y\xfcr\xfcrl\xfck: 1 Kas\u0131m 2026) md. 8/6 uyar\u0131nca 15\u201318 ya\u015f kullan\u0131c\u0131lar i\xe7in ald\u0131\u011f\u0131m\u0131z \xf6nlemler.',sections:[{h:'15 ya\u015f s\u0131n\u0131r\u0131',p:['15 ya\u015f\u0131n\u0131 doldurmam\u0131\u015f ki\u015filere hesap a\xe7\u0131lmaz. Bu ya\u015fta oldu\u011fu anla\u015f\u0131lan hesaplar, kullan\u0131c\u0131 bilgilendirilerek kapat\u0131l\u0131r.','Ya\u015f grubuna itiraz \xfccretsizdir, T\xfcrk\xe7e yap\u0131l\u0131r ve bir ki\u015fi taraf\u0131ndan incelenir (Ayarlar > Yard\u0131m > Ya\u015f itiraz\u0131). \u0130tiraz sonu\xe7lanana kadar veriler silinmez.','Mevcut hesaplar\u0131n ya\u015f\u0131 en ge\xe7 31 Mart 2027\u2019ye kadar e-Devlet ya\u015f belirteciyle do\u011frulan\u0131r.']},{h:'15\u201318 ya\u015f korumalar\u0131',p:['Hesap gizli a\xe7\u0131l\u0131r; herkese a\xe7\u0131k yapmak yaln\u0131zca bir se\xe7enektir.','Takip\xe7i ve takip listesi yaln\u0131zca kullan\u0131c\u0131n\u0131n kendisine g\xf6r\xfcn\xfcr.','Yaln\u0131zca kullan\u0131c\u0131n\u0131n takip etti\u011fi hesaplar ona mesaj g\xf6nderebilir; mesajlarda \u201cg\xf6r\xfcld\xfc\u201d bilgisi g\xf6sterilmez.','Hesap ba\u015fkalar\u0131na \xf6nerilmez ve aramada yaln\u0131zca takip ili\u015fkisi olanlara g\xf6r\xfcn\xfcr.','Foto\u011fraf, video ve anlar\u0131nda ba\u015fkalar\u0131n\u0131n ekran g\xf6r\xfcnt\xfcs\xfc almas\u0131 teknik olarak engellenir.','Videolar kendili\u011finden oynamaz; dikey ak\u0131\u015flarda sonsuz kayd\u0131rma yoktur.','Canl\u0131 yay\u0131n a\xe7\u0131lamaz, profil \xe7\u0131kar\u0131m\u0131na dayal\u0131 ki\u015fisel reklam g\xf6sterilmez, rehber e\u015fle\u015ftirmesi yap\u0131lmaz.']},{h:'Ebeveyn denetimi',p:['Ebeveyn, \xe7ocu\u011funun \xfcretti\u011fi tek kullan\u0131ml\u0131k kodla hesab\u0131 ba\u011flar; g\xfcnl\xfck s\xfcre s\u0131n\u0131r\u0131 koyabilir, hesab\u0131n gizli kalmas\u0131n\u0131 ve yaln\u0131zca takip edilenlerin yorum yapmas\u0131n\u0131 sa\u011flayabilir.','\xc7ocuk, denetimi ebeveyninin onay\u0131 olmadan kald\u0131ramaz. 18 ya\u015f doldu\u011funda denetim kendili\u011finden sona erer.']},{h:'\u0130tiraz istatistikleri',p:['Ya\u015f itirazlar\u0131na ili\u015fkin y\u0131ll\u0131k istatistikler her y\u0131l bu sayfada yay\u0131mlan\u0131r. [\u0130lk yay\u0131n: 2027]']}]},{key:'telif',title:'Telif ve \u0130\xe7erik Bildirimi',updated:'28 Ekim 2026',sections:[{h:'Hakk\u0131n\u0131 ihlal eden bir i\xe7erik mi g\xf6rd\xfcn?',p:['\u0130\xe7erikteki \u201c\u2026\u201d men\xfcs\xfcnden \u201c\u015eikayet et\u201di se\xe7ebilir ya da Ayarlar > Yard\u0131m \xfczerinden bize yazabilirsin.',`Telif hakk\u0131 veya ki\u015filik hakk\u0131 ihlali bildirimlerini ${k} adresine; hak sahibi oldu\u011funu g\xf6steren bilgi, i\xe7eri\u011fin ba\u011flant\u0131s\u0131 ve ileti\u015fim bilgilerinle g\xf6nder. 5651 say\u0131l\u0131 Kanun kapsam\u0131ndaki bildirimler en ge\xe7 24 saat i\xe7inde de\u011ferlendirilir.`]},{h:'Haber kaynaklar\u0131',p:['Haberler sekmesinde TRT Haber, BBC T\xfcrk\xe7e, DW T\xfcrk\xe7e, CNN T\xfcrk, Habert\xfcrk ve S\xf6zc\xfc\u2019n\xfcn herkese a\xe7\u0131k haber ak\u0131\u015flar\u0131ndan yaln\u0131zca ba\u015fl\u0131k, k\u0131sa \xf6zet ve g\xf6rsel g\xf6sterilir; haberin tamam\u0131 kayna\u011f\u0131n sitesinde a\xe7\u0131l\u0131r. Kaynak kurulu\u015flar i\xe7eriklerinin kald\u0131r\u0131lmas\u0131n\u0131 istedi\u011finde hemen kald\u0131r\u0131l\u0131r.']}]}],t=l=>s.find(n=>n.key===l)},989,[]);